// Consent gates: declining an introduction really removes its private conversations.
function allowed(s,a){const f=s.flags;
 if(a.who==='serega'&&f.denied)return false;
 if(a.who==='killer')return f.val_mode==='question'&&f.killer_mode!=='refuse'&&f.killer_reply!=='block';
 if(a.who==='marat'&&!s.contacts.marat.known)return false;
 if(a.who==='sonny')return !!f.vacha_notice&&f.vacha_notice!=='none';
 if(a.who==='archive'&&a.id[0]==='W')return !!f.archive_intro&&f.archive_intro!=='distance';
 if(a.who==='master')return !!f.master_intro&&f.master_intro!=='private';
 if(a.who==='strelok')return !!f.bar_music&&f.bar_music!=='private';
 return true;
}
function boot(s){const f=s.flags;if(f.campaign)return;f.cellarFinished=true;f.finished=false;f.campaign=true;s.campaign={day:0,done:[],skipped:[],between:false,answers:{},receipts:{},reply:null};
 f.photo_route=f.route;f.theory_mode=f.theory_mode||f.marat_mode||(f.publicRumor?'spread':f.maratRequested?'challenge':'ignore');f.rumor_mode=f.rumor_mode||(f.publicRumor?'speculation':'contained');f.cellar_mode=f.cellarMode==='warn'?'careful':f.cellarMode==='ask'?'identify':'leave';
 for(const [k,c]of Object.entries(s.contacts)){if(c.node==='ending'){c.node='settled';c.status='available';}}
 schedule(s,0);
}
function schedule(s,d){const p=s.campaign;p.day=d;p.between=false;let at=s.now;
 for(const a of data.scenes.filter(a=>a.day===d).sort((a,b)=>a.at-b.at)){at=Math.max(a.at,at+1);H.event(s,'story-'+a.id,at,a.who,'story:'+a.id,H.PEOPLE[a.who].name+': '+a.title+'.');}
}
function busy(s){return Object.values(s.contacts).some(c=>c.known&&(!['settled','wait','ending'].includes(c.node)||c.pending.length));}
function tick(s){if(!s.flags.campaign||s.flags.finished)return;if(!s.events.length&&!busy(s)){if(s.campaign.day<10)s.campaign.between=true;else{go(s,'tomazik','book:closing');s.focus='tomazik';}}}
function go(s,k,n,at){H.unlock(s,k);H.go(s,k,n,at);}
function awaitingIntroduction(s,a){const gate={sonny:'vacha_notice',archive:a.id[0]==='W'?'archive_intro':null,master:'master_intro',strelok:'bar_music'}[a.who];return !!gate&&s.flags[gate]===undefined;}
function receive(s,e){const id=e.node.slice(6),a=scenes[id];if(!a)return false;if(awaitingIntroduction(s,a)){s.campaign.deferred ||= [];if(!s.campaign.deferred.some(x=>x.node===e.node))s.campaign.deferred.push(e);return true;}if(!allowed(s,a)){s.campaign.skipped.push(id);return true;}s.campaign.receipts[id]=e.originAt??e.at;return false;}
function releaseIntroductions(s){const held=s.campaign.deferred||[];s.campaign.deferred=[];for(const e of held.sort((a,b)=>a.at-b.at)){const a=scenes[e.node.slice(6)];if(awaitingIntroduction(s,a))s.campaign.deferred.push(e);else if(allowed(s,a))H.event(s,'released-'+e.id,s.now,e.who,e.node,e.label,e.at);else s.campaign.skipped.push(a.id);}}

function current(s,k){const n=s.contacts[k].node;return n?.startsWith('story:')?scenes[n.slice(6)]:null;}
function isNode(n){return n==='book:closing'||n==='book:credits'||/^reply:[A-Z]\d\d$/.test(n)&&!!scenes[n.slice(6)]||n?.startsWith('story:')&&!!scenes[n.slice(6)];}
function resolvedCellar(f){return f.alla_final==='help'&&(f.help_route==='official'||f.cellarEnding==='report')?'alive':f.alla_final==='record'&&(f.help_route==='official'||f.cellarEnding==='report')?'unknown':'gone';}
